import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int bufLen, bufPtr;

    static int read() throws IOException {
        if (bufPtr == bufLen) {
            bufLen = System.in.read(BUF, 0, BUF.length);
            bufPtr = 0;
            if (bufLen <= 0) return -1;
        }
        return BUF[bufPtr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        long[] vals = a.clone();
        Arrays.sort(vals);
        int size = 0;
        for (int i = 0; i < n; i++) if (i == 0 || vals[i] != vals[i - 1]) vals[size++] = vals[i];
        int[] id = new int[n], last = new int[size];
        for (int i = 0; i < n; i++) {
            id[i] = Arrays.binarySearch(vals, 0, size, a[i]);
            last[id[i]] = i;
        }
        // Overlapping first..last spans form blocks; a block with d values needs d - 1 merges.
        int end = -1, blocks = 0;
        for (int i = 0; i < n; i++) {
            end = Math.max(end, last[id[i]]);
            if (i == end) blocks++;
        }
        System.out.println(size - blocks);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"slices"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	a := make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	vals := slices.Clone(a)
	slices.Sort(vals)
	vals = slices.Compact(vals)
	id := make([]int, n)
	last := make([]int, len(vals))
	for i, v := range a {
		id[i], _ = slices.BinarySearch(vals, v)
		last[id[i]] = i
	}
	// Overlapping first..last spans form blocks; a block with d values needs d - 1 merges.
	end, blocks := -1, 0
	for i := 0; i < n; i++ {
		end = max(end, last[id[i]])
		if i == end {
			blocks++
		}
	}
	fmt.Println(len(vals) - blocks)
}
